doc = DocumentManager.Instance.CurrentDBDocument
MM = 1.0 / 304.8
log = []


def ename(e):
    try:
        return e.Name
    except Exception:
        return Element.Name.__get__(e)


def tag_of(e):
    p = e.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)
    return p.AsString() if p is not None else None


def set_tag(e):
    p = e.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)
    if p is not None and not p.IsReadOnly:
        p.Set(TAG)


def bip(name):
    return getattr(BuiltInParameter, name, None)


def snap_mm(mm):
    mm = int(round(mm / 10.0) * 10)
    for target in (200, 300):
        if abs(mm - target) <= 35:
            return target
    return mm


levels = sorted(FilteredElementCollector(doc).OfClass(Level).ToElements(), key=lambda l: l.Elevation)
lv_by_name = dict((ename(l), l) for l in levels)
images = {}
for img in FilteredElementCollector(doc).OfClass(ImageInstance).ToElements():
    images[ename(doc.GetElement(img.GetTypeId())).strip().lower()] = img

TransactionManager.Instance.EnsureInTransaction(doc)

# ── 0. 이전 결과 삭제 ──
def delete_tagged(cls_or_cat, is_cat=False):
    col = FilteredElementCollector(doc).WhereElementIsNotElementType()
    col = col.OfCategory(cls_or_cat) if is_cat else col.OfClass(cls_or_cat)
    ids = [e.Id for e in col.ToElements() if tag_of(e) == TAG]
    for i in ids:
        try:
            doc.Delete(i)
        except Exception:
            pass
    return len(ids)

if RUN_DOORS or RUN_WALLS:
    n = delete_tagged(BuiltInCategory.OST_Doors, True)
    if n: log.append('이전 자동생성 문 %d개 삭제' % n)
if RUN_WINDOWS or RUN_WALLS:
    n = delete_tagged(BuiltInCategory.OST_Windows, True)
    if n: log.append('이전 자동생성 창 %d개 삭제' % n)
if RUN_WALLS:
    n = delete_tagged(Wall)
    if n: log.append('이전 자동생성 벽 %d개 삭제' % n)
if RUN_FLOORS:
    n = delete_tagged(Floor)
    if n: log.append('이전 자동생성 바닥 %d개 삭제' % n)

# ── 1. PDF 정렬 ──
if ALIGN_TO_1F and '1.pdf' in images:
    c1 = images['1.pdf'].GetLocation(BoxPlacement.Center)
    for fl in ['2', '3', '4', '5', '6', '7']:
        img = images.get('%s.pdf' % fl)
        if img is None or abs(img.Width - images['1.pdf'].Width) > 1e-3:
            continue
        was = img.Pinned
        if was: img.Pinned = False
        img.SetLocation(XYZ(c1.X, c1.Y, img.GetLocation(BoxPlacement.Center).Z), BoxPlacement.Center)
        if was: img.Pinned = True
    doc.Regenerate()


def frame(fl):
    img = images.get('%s.pdf' % fl)
    lvl = lv_by_name.get(FLOOR_LEVEL[fl])
    if img is None or lvl is None:
        return None
    c = img.GetLocation(BoxPlacement.Center)
    k = img.Width / PX_W
    left, top = c.X - img.Width / 2.0, c.Y + img.Height / 2.0
    idx = levels.index(lvl)
    nxt = levels[idx + 1] if idx + 1 < len(levels) else None
    def P(x, y):
        return XYZ(left + x * k, top - y * k, lvl.Elevation)
    return {'P': P, 'k': k, 'lvl': lvl, 'nxt': nxt}


# ── 2. 벽 ──
base_wt = next((w for w in FilteredElementCollector(doc).OfClass(WallType).ToElements() if w.Kind == WallKind.Basic), None)
wt_cache = {}

def wall_type(mm):
    name = 'PDF벽_%dmm' % mm
    if name not in wt_cache:
        found = [w for w in FilteredElementCollector(doc).OfClass(WallType).ToElements() if ename(w) == name]
        if found:
            wt_cache[name] = found[0]
        else:
            wt = base_wt.Duplicate(name)
            wt.SetCompoundStructure(CompoundStructure.CreateSingleLayerCompoundStructure(
                MaterialFunctionAssignment.Structure, mm * MM, ElementId.InvalidElementId))
            wt_cache[name] = wt
    return wt_cache[name]

walls_by_floor = {}
def run_walls():
    for fl in RUN_FLOORS_LIST:
        F = frame(fl)
        if F is None:
            log.append('%s층: PDF 또는 레벨 없음' % fl); continue
        P, k, lvl, nxt = F['P'], F['k'], F['lvl'], F['nxt']
        made = 0
        items = [('L', w) for w in DATA[fl]['walls']] + [('A', a) for a in DATA[fl]['arcs']]
        for kind, w in items:
            try:
                if kind == 'L':
                    p1, p2 = P(w[0], w[1]), P(w[2], w[3])
                    if p1.DistanceTo(p2) < 50 * MM: continue
                    crv = Line.CreateBound(p1, p2); t = w[4]; inner = w[5]
                else:
                    crv = Arc.Create(P(w[0], w[1]), P(w[4], w[5]), P(w[2], w[3])); t = w[6]; inner = 0
                wt = wall_type(snap_mm(t * k / MM))
                if nxt is not None:
                    wall = Wall.Create(doc, crv, wt.Id, lvl.Id, nxt.Elevation - lvl.Elevation, 0.0, False, False)
                    wall.get_Parameter(BuiltInParameter.WALL_HEIGHT_TYPE).Set(nxt.Id)
                else:
                    h = (ROOF_STAIR_MM if inner else PARAPET_MM) * MM
                    wall = Wall.Create(doc, crv, wt.Id, lvl.Id, h, 0.0, False, False)
                set_tag(wall); made += 1
            except Exception as ex:
                log.append('%s층 벽 실패: %s' % (fl, ex))
        log.append('%s층 벽 %d개' % (fl, made))
    doc.Regenerate()

if RUN_WALLS:
    try:
        run_walls()
    except Exception as ex:
        log.append('벽 단계 오류: %s' % ex)

# 층별 자동생성 벽 목록 (창/문 호스트 찾기용)
for w in FilteredElementCollector(doc).OfClass(Wall).ToElements():
    if tag_of(w) == TAG and hasattr(w.Location, 'Curve'):
        walls_by_floor.setdefault(w.LevelId.ToString(), []).append(w)


def host_wall(lvl, pt):
    best = None
    for w in walls_by_floor.get(lvl.Id.ToString(), []):
        c = w.Location.Curve
        if c.GetType().Name != 'Line':
            continue
        r = c.Project(pt)
        if r is None: continue
        p0, p1 = c.GetEndParameter(0), c.GetEndParameter(1)
        if not (min(p0, p1) + 0.05 < r.Parameter < max(p0, p1) - 0.05):
            continue
        d = r.Distance
        if d < 0.5 and (best is None or d < best[0]):
            best = (d, w)
    return best[1] if best else None


# ── 3. 바닥 ──
def run_floors():
    fts = [f for f in FilteredElementCollector(doc).OfClass(FloorType).ToElements() if not f.IsFoundationSlab]
    name = 'PDF슬래브_%dmm' % SLAB_MM
    ft = next((f for f in fts if ename(f) == name), None)
    if ft is None:
        src = next((f for f in fts if f.GetCompoundStructure() is not None), fts[0])
        ft = src.Duplicate(name)
    # 기존 바닥 구조를 그대로 두고 구조층 두께만 조정해 총 두께를 SLAB_MM으로 맞춤
    try:
        cs = ft.GetCompoundStructure()
        total = sum(cs.GetLayerWidth(i) for i in range(cs.LayerCount))
        idx = cs.StructuralMaterialIndex
        if idx < 0:
            idx = cs.GetFirstCoreLayerIndex()
        if idx < 0:
            idx = 0
        new_w = cs.GetLayerWidth(idx) + (SLAB_MM * MM - total)
        if new_w > 10 * MM:
            cs.SetLayerWidth(idx, new_w)
            ft.SetCompoundStructure(cs)
        else:
            log.append('바닥 유형 두께 조정 불가 - 기존 두께 사용')
    except Exception as ex:
        log.append('바닥 유형 두께 조정 실패(기존 두께 사용): %s' % ex)

    def loop(pts, P):
        cl = CurveLoop()
        xyz = [P(x, y) for x, y in pts]
        clean = []
        for q in xyz:
            if not clean or q.DistanceTo(clean[-1]) > 5 * MM:
                clean.append(q)
        if clean[0].DistanceTo(clean[-1]) <= 5 * MM:
            clean.pop()
        for i in range(len(clean)):
            cl.Append(Line.CreateBound(clean[i], clean[(i + 1) % len(clean)]))
        return cl

    for fl in RUN_FLOORS_LIST:
        F = frame(fl)
        if F is None: continue
        try:
            loops = List[CurveLoop]()
            loops.Add(loop(DATA[fl]['slab'], F['P']))
            for h in DATA[fl]['holes']:
                loops.Add(loop(h, F['P']))
            fl_el = Floor.Create(doc, loops, ft.Id, F['lvl'].Id)
            set_tag(fl_el)
            log.append('%s층 바닥 생성 (개구부 %d개)' % (fl, len(DATA[fl]['holes'])))
        except Exception as ex:
            log.append('%s층 바닥 실패: %s' % (fl, ex))
    doc.Regenerate()

if RUN_FLOORS:
    try:
        run_floors()
    except Exception as ex:
        log.append('바닥 단계 오류: %s' % ex)


# ── 4. 창 / 문 공통 ──
def symbols(cat):
    return [s for s in FilteredElementCollector(doc).OfClass(FamilySymbol).OfCategory(cat).ToElements()]

def fam_name(s):
    try:
        return s.Family.Name
    except Exception:
        return ''

def sized_symbol(base, prefix, mm, width_bips):
    name = '%s_%dmm' % (prefix, mm)
    for sid in base.Family.GetFamilySymbolIds():
        s = doc.GetElement(sid)
        if ename(s) == name:
            return s
    try:
        s = base.Duplicate(name)
    except Exception:
        return base
    ok = False
    for b in width_bips:
        bp = bip(b)
        p = s.get_Parameter(bp) if bp is not None else None
        if p is not None and not p.IsReadOnly:
            p.Set(mm * MM); ok = True; break
    if not ok:
        for nm in ('폭', 'Width', '너비'):
            p = s.LookupParameter(nm)
            if p is not None and not p.IsReadOnly:
                p.Set(mm * MM); ok = True; break
    if not ok:
        log.append('%s: 폭 변경 불가 패밀리 - 기본 크기로 배치' % fam_name(base))
    return s

def place(sym, P, x1, y1, x2, y2, lvl):
    if not sym.IsActive:
        sym.Activate(); doc.Regenerate()
    a, b = P(x1, y1), P(x2, y2)
    mid = XYZ((a.X + b.X) / 2, (a.Y + b.Y) / 2, lvl.Elevation)
    w = host_wall(lvl, mid)
    if w is None:
        return None, a, b, mid
    inst = doc.Create.NewFamilyInstance(mid, sym, w, lvl, StructuralType.NonStructural)
    set_tag(inst)
    return inst, a, b, mid


# ── 5. 창 ──
def run_windows():
    ws = symbols(BuiltInCategory.OST_Windows)
    if not ws:
        log.append('창 패밀리가 프로젝트에 없음 → 삽입 탭에서 창 패밀리를 로드하세요')
    else:
        bad = ('코너', 'Corner', 'corner', '천창', 'Skylight')
        ok_ws = [s for s in ws if not any(k in fam_name(s) for k in bad)] or ws
        pref = [s for s in ok_ws if fam_name(s) in ('고정', 'Fixed', 'M_Fixed')]
        pref = pref or [s for s in ok_ws if any(k in fam_name(s) for k in ('고정', 'Fixed', 'fixed'))]
        base = (pref or ok_ws)[0]
        cnt = 0
        for fl in RUN_FLOORS_LIST:
            F = frame(fl)
            if F is None: continue
            for o in DATA[fl]['windows']:
                try:
                    mm = int(round(math.hypot(o[2] - o[0], o[3] - o[1]) * F['k'] / MM / 50.0) * 50)
                    if mm < 300: continue
                    sym = sized_symbol(base, 'PDF창', mm, ['WINDOW_WIDTH', 'FAMILY_WIDTH_PARAM', 'FAMILY_ROUGH_WIDTH_PARAM'])
                    inst, a, b, mid = place(sym, F['P'], o[0], o[1], o[2], o[3], F['lvl'])
                    if inst is None:
                        log.append('%s층 창(%dmm): 호스트 벽 없음' % (fl, mm))
                    else:
                        cnt += 1
                except Exception as ex:
                    log.append('%s층 창 실패: %s' % (fl, ex))
        log.append('창 %d개 배치 (패밀리: %s)' % (cnt, fam_name(base)))

if RUN_WINDOWS:
    try:
        run_windows()
    except Exception as ex:
        log.append('창 단계 오류: %s' % ex)

# ── 6. 문 ──
def run_doors():
    ds = symbols(BuiltInCategory.OST_Doors)
    if not ds:
        log.append('문 패밀리가 프로젝트에 없음 → 삽입 탭에서 문 패밀리를 로드하세요')
    else:
        dbl = [s for s in ds if any(k in fam_name(s) + ename(s) for k in ('양', '이중', 'Double', 'double'))]
        dbl_ids = set(s.Id.ToString() for s in dbl)
        sgl = [s for s in ds if s.Id.ToString() not in dbl_ids and not any(k in fam_name(s) for k in ('커튼', 'Curtain', '차고', 'Garage'))] or ds
        cnt = 0
        for fl in RUN_FLOORS_LIST:
            F = frame(fl)
            if F is None: continue
            for d in DATA[fl]['doors']:
                try:
                    x1, y1, x2, y2, t, nx, ny, leaves, hinge = d
                    mm = int(round(math.hypot(x2 - x1, y2 - y1) * F['k'] / MM / 50.0) * 50)
                    base = dbl[0] if (leaves == 2 and dbl) else sgl[0]
                    sym = sized_symbol(base, 'PDF양문' if base.Id.ToString() in dbl_ids else 'PDF문', mm,
                                       ['DOOR_WIDTH', 'FAMILY_WIDTH_PARAM', 'FAMILY_ROUGH_WIDTH_PARAM'])
                    inst, a, b, mid = place(sym, F['P'], x1, y1, x2, y2, F['lvl'])
                    if inst is None:
                        log.append('%s층 문(%dmm): 호스트 벽 없음' % (fl, mm)); continue
                    doc.Regenerate()
                    swing = XYZ(nx, -ny, 0)                       # PDF y축은 아래 방향
                    want = swing if SWING_TO_FACING else swing.Negate()
                    if inst.FacingOrientation.DotProduct(want) < 0:
                        inst.flipFacing(); doc.Regenerate()
                    if hinge == 'a' and leaves == 1:
                        hv = XYZ(a.X - mid.X, a.Y - mid.Y, 0)
                        dot = inst.HandOrientation.DotProduct(hv)
                        if (dot < 0) == HINGE_TO_HAND:
                            inst.flipHand(); doc.Regenerate()
                    cnt += 1
                except Exception as ex:
                    log.append('%s층 문 실패: %s' % (fl, ex))
        log.append('문 %d개 배치 (외문: %s / 양문: %s)' % (cnt, fam_name(sgl[0]), fam_name(dbl[0]) if dbl else '없음 → 외문으로 대체'))

if RUN_DOORS:
    try:
        run_doors()
    except Exception as ex:
        log.append('문 단계 오류: %s' % ex)

TransactionManager.Instance.TransactionTaskDone()
OUT = log
